sp_widget.client_script:
api.controller = function () {
    /* widget controller */
    var c = this;
};

sp_widget.css:
.ibar-kpi-card {
  text-align: center;
  padding: 16px 8px;
  border-radius: 4px;
  border: 1px solid $border-tertiary;
  margin-bottom: 16px;
  background: $background-primary;
}
.ibar-kpi-value {
  font-size: 32px;
  font-weight: 700;
  color: $text-color;
  line-height: 1.2;
}
.ibar-kpi-label {
  font-size: 12px;
  color: $text-muted;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-top: 4px;
}
.ibar-kpi-info {
  border-left: 3px solid $brand-info;
}
.ibar-kpi-primary {
  border-left: 3px solid $brand-primary;
}
.ibar-kpi-success {
  border-left: 3px solid $brand-success;
}

sp_widget.script:
(function() {
  data.kpis = {
    total: 0,
    in_progress: 0,
    submitted: 0,
    completed: 0,
    overdue: 0
  };
  data.userName = "";

  try {
    var userId = gs.getUserID();

    // Get user display name
    var userGr = new GlideRecord("sys_user");
    if (userGr.get(userId)) {
      data.userName = userGr.getDisplayValue("name");
    }

    // Get assignments for current user
    var assignmentGr = new GlideRecord("x_1433041_identi_0_assignment");
    assignmentGr.addQuery("user", userId);
    assignmentGr.setLimit(200);
    assignmentGr.query();

    var appIds = [];
    while (assignmentGr.next()) {
      appIds.push(assignmentGr.getValue("application"));
    }

    if (appIds.length === 0) {
      return;
    }

    // Count by status
    var appGr = new GlideRecord("x_1433041_identi_0_application");
    appGr.addQuery("sys_id", "IN", appIds.join(","));
    appGr.addQuery("active", true);
    appGr.setLimit(200);
    appGr.query();

    while (appGr.next()) {
      data.kpis.total++;
      var status = appGr.getValue("questionnaire_status");
      if (status === "in_progress" || status === "draft" || status === "clarification_requested") {
        data.kpis.in_progress++;
      } else if (status === "submitted" || status === "admin_review") {
        data.kpis.submitted++;
      } else if (status === "completed" || status === "build_ready") {
        data.kpis.completed++;
      }
    }
  } catch (e) {
    gs.error("IBAR Progress Summary widget error: " + e.message);
  }
})();
